import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第七章 国家出资公司组织机构的特别规定","description":"","frontmatter":{"title":"第七章 国家出资公司组织机构的特别规定","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第七章：国家出资公司组织机构的特别规定.md"},"headers":[],"relativePath":"blogs/CL/diqizhang：guojiaochugongsizuzhijigoudetebieguiding.md","filePath":"blogs/CL/第七章：国家出资公司组织机构的特别规定.md"}'),i={name:"blogs/CL/diqizhang：guojiaochugongsizuzhijigoudetebieguiding.md"};function h(l,a,n,d,s,_){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="第七章-国家出资公司组织机构的特别规定" tabindex="-1">第七章 国家出资公司组织机构的特别规定 <a class="header-anchor" href="#第七章-国家出资公司组织机构的特别规定" aria-label="Permalink to &quot;第七章 国家出资公司组织机构的特别规定&quot;">​</a></h1><h3 id="第一百六十八条" tabindex="-1">第一百六十八条 <a class="header-anchor" href="#第一百六十八条" aria-label="Permalink to &quot;第一百六十八条&quot;">​</a></h3><p>八条国家出资公司的组织机构，适用本章规定；本章没有规定的，适用本法其他规定。 本法所称国家出资公司，是指国家出资的国有独资公司、国有资本控股公司，包括国家出资的有限责任公司、股份有限公司。</p><h3 id="第一百六十九条" tabindex="-1">第一百六十九条 <a class="header-anchor" href="#第一百六十九条" aria-label="Permalink to &quot;第一百六十九条&quot;">​</a></h3><p>九条国家出资公司，由国务院或者地方人民政府分别代表国家依法履行出资人职责，享有出资人权益。国务院或者地方人民政府可以授权国有资产监督管理机构或者其他部门、机构代表本级人民政府对国家出资公司履行出资人职责。 代表本级人民政府履行出资人职责的机构、部门，以下统称为履行出资人职责的机构。</p><h3 id="第一百七十条" tabindex="-1">第一百七十条 <a class="header-anchor" href="#第一百七十条" aria-label="Permalink to &quot;第一百七十条&quot;">​</a></h3><p>十条国家出资公司中中国共产党的组织，按照中国共产党章程的规定发挥领导作用，研究讨论公司重大经营管理事项，支持公司的组织机构依法行使职权。</p><h3 id="第一百七十一条" tabindex="-1">第一百七十一条 <a class="header-anchor" href="#第一百七十一条" aria-label="Permalink to &quot;第一百七十一条&quot;">​</a></h3><p>一条国有独资公司章程由履行出资人职责的机构制定。</p><h3 id="第一百七十二条" tabindex="-1">第一百七十二条 <a class="header-anchor" href="#第一百七十二条" aria-label="Permalink to &quot;第一百七十二条&quot;">​</a></h3><p>二条国有独资公司不设股东会，由履行出资人职责的机构行使股东会职权。履行出资人职责的机构可以授权公司董事会行使股东会的部分职权，但公司章程的制定和修改，公司的合并、分立、解散、申请破产，增加或者减少注册资本，分配利润，应当由履行出资人职责的机构决定。</p><h3 id="第一百七十三条" tabindex="-1">第一百七十三条 <a class="header-anchor" href="#第一百七十三条" aria-label="Permalink to &quot;第一百七十三条&quot;">​</a></h3><p>三条国有独资公司的董事会依照本法规定行使职权。 国有独资公司的董事会成员中，应当过半数为外部董事，并应当有公司职工代表。 董事会成员由履行出资人职责的机构委派；但是，董事会成员中的职工代表由公司职工代表大会选举产生。 董事会设董事长一人，可以设副董事长。董事长、副董事长由履行出资人职责的机构从董事会成员中指定。</p><h3 id="第一百七十四条" tabindex="-1">第一百七十四条 <a class="header-anchor" href="#第一百七十四条" aria-label="Permalink to &quot;第一百七十四条&quot;">​</a></h3><p>四条国有独资公司的经理由董事会聘任或者解聘。 经履行出资人职责的机构同意，董事会成员可以兼任经理。</p><h3 id="第一百七十五条" tabindex="-1">第一百七十五条 <a class="header-anchor" href="#第一百七十五条" aria-label="Permalink to &quot;第一百七十五条&quot;">​</a></h3><p>五条国有独资公司的董事、高级管理人员，未经履行出资人职责的机构同意，不得在其他有限责任公司、股份有限公司或者其他经济组织兼职。</p><h3 id="第一百七十六条" tabindex="-1">第一百七十六条 <a class="header-anchor" href="#第一百七十六条" aria-label="Permalink to &quot;第一百七十六条&quot;">​</a></h3><p>六条国有独资公司在董事会中设置由董事组成的审计委员会行使本法规定的监事会职权的，不设监事会或者监事。</p><h3 id="第一百七十七条" tabindex="-1">第一百七十七条 <a class="header-anchor" href="#第一百七十七条" aria-label="Permalink to &quot;第一百七十七条&quot;">​</a></h3><p>七条国家出资公司应当依法建立健全内部监督管理和风险控制制度，加强内部合规管理。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',23)])])}const p=e(i,[["render",h]]);export{u as __pageData,p as default};
